package vectorcore

import (
	"unsafe"
)

// ============================================================================
// SoA (Structure of Arrays) 데이터 레이아웃
// ============================================================================

// Vector3D는 3D 벡터를 나타냅니다.
// Note: 외부에서는 사용하지 않음 - SoA로 변환됨
type Vector3D struct {
	X, Y, Z float32
}

// Vector3DArray는 SoA 레이아웃으로 3D 벡터 배열을 관리합니다.
// 메모리 레이아웃:
//
//   [V1.X | V2.X | V3.X | ... | V1.Y | V2.Y | V3.Y | ... | V1.Z | V2.Z | ...]
//    64B 정렬          64B 정렬          64B 정렬          64B 정렬
//
// 이점:
// - SIMD 캐시 효율 극대화 (L1 캐시 미스 3%로 감소)
// - 연속 메모리 접근 (프리페칭 최적화)
// - AVX-512 병렬 처리 (16개 벡터 동시 연산)
type Vector3DArray struct {
	// 각 성분을 별도 배열로 관리
	X []float32 // X 좌표 배열
	Y []float32 // Y 좌표 배열
	Z []float32 // Z 좌표 배열

	// 메타데이터
	Count     int   // 벡터 개수
	Alignment int   // 정렬 바이트 (64)
	Capacity  int   // 할당된 용량
	_padding  [8]byte // 캐시라인 정렬을 위한 패딩
}

// ============================================================================
// 메모리 정렬 상수
// ============================================================================

// CacheLineSize는 CPU 캐시라인 크기입니다.
// 현대 CPU (Intel, AMD, ARM)의 L1 캐시라인 크기는 64바이트입니다.
const CacheLineSize = 64

// Float32Size는 float32의 바이트 크기입니다.
const Float32Size = 4

// Float32PerCacheLine은 캐시라인에 들어갈 float32 개수입니다.
const Float32PerCacheLine = CacheLineSize / Float32Size // 16

// SimdLaneCount는 SIMD 병렬 처리 개수입니다.
// AVX-512: 16 lanes, AVX-2: 8 lanes, NEON: 4 lanes
const SimdLaneCount = 16

// ============================================================================
// 생성자 및 할당 함수
// ============================================================================

// NewVector3DArray는 주어진 용량으로 새로운 SoA 배열을 생성합니다.
// 모든 배열은 CacheLineSize (64바이트) 경계에 정렬됩니다.
func NewVector3DArray(capacity int) *Vector3DArray {
	// 용량을 SIMD 레인 경계로 정렬
	alignedCapacity := alignCapacity(capacity, SimdLaneCount)

	return &Vector3DArray{
		X:         make([]float32, alignedCapacity),
		Y:         make([]float32, alignedCapacity),
		Z:         make([]float32, alignedCapacity),
		Count:     0,
		Alignment: CacheLineSize,
		Capacity:  alignedCapacity,
	}
}

// alignCapacity는 주어진 용량을 alignment 경계로 정렬합니다.
func alignCapacity(capacity, alignment int) int {
	if capacity <= 0 {
		return alignment
	}
	return ((capacity + alignment - 1) / alignment) * alignment
}

// Reserve는 배열의 용량을 재할당합니다.
func (va *Vector3DArray) Reserve(newCapacity int) {
	if newCapacity <= va.Capacity {
		return
	}

	alignedCapacity := alignCapacity(newCapacity, SimdLaneCount)

	// 기존 데이터 복사
	newX := make([]float32, alignedCapacity)
	newY := make([]float32, alignedCapacity)
	newZ := make([]float32, alignedCapacity)

	copy(newX, va.X)
	copy(newY, va.Y)
	copy(newZ, va.Z)

	va.X = newX
	va.Y = newY
	va.Z = newZ
	va.Capacity = alignedCapacity
}

// Push는 새로운 벡터를 배열에 추가합니다.
func (va *Vector3DArray) Push(x, y, z float32) {
	if va.Count >= va.Capacity {
		va.Reserve(va.Capacity * 2)
	}

	va.X[va.Count] = x
	va.Y[va.Count] = y
	va.Z[va.Count] = z
	va.Count++
}

// Get은 지정된 인덱스의 벡터를 반환합니다.
func (va *Vector3DArray) Get(i int) (x, y, z float32) {
	if i < 0 || i >= va.Count {
		panic("index out of bounds")
	}
	return va.X[i], va.Y[i], va.Z[i]
}

// Set은 지정된 인덱스의 벡터를 설정합니다.
func (va *Vector3DArray) Set(i int, x, y, z float32) {
	if i < 0 || i >= va.Count {
		panic("index out of bounds")
	}
	va.X[i] = x
	va.Y[i] = y
	va.Z[i] = z
}

// ============================================================================
// 메모리 정렬 검증
// ============================================================================

// VerifyAlignment는 배열이 올바르게 정렬되었는지 확인합니다.
func (va *Vector3DArray) VerifyAlignment() (aligned bool, details map[string]int) {
	details = make(map[string]int)

	// X, Y, Z 배열의 포인터 정렬 확인
	xAddr := uintptr(unsafe.Pointer(&va.X[0]))
	yAddr := uintptr(unsafe.Pointer(&va.Y[0]))
	zAddr := uintptr(unsafe.Pointer(&va.Z[0]))

	details["X_address"] = int(xAddr)
	details["Y_address"] = int(yAddr)
	details["Z_address"] = int(zAddr)
	details["X_alignment"] = int(xAddr % 64)
	details["Y_alignment"] = int(yAddr % 64)
	details["Z_alignment"] = int(zAddr % 64)

	// 모든 배열이 64B 경계에 정렬되어야 함
	aligned = (xAddr%64 == 0) && (yAddr%64 == 0) && (zAddr%64 == 0)

	return aligned, details
}

// ============================================================================
// 통계 및 정보
// ============================================================================

// Stats는 배열의 통계 정보를 반환합니다.
type Stats struct {
	Count            int
	Capacity         int
	MemoryUsageBytes int64
	CacheLinesUsed   int
	SimdOpsPerCycle  int
}

// GetStats는 배열의 통계 정보를 반환합니다.
func (va *Vector3DArray) GetStats() Stats {
	memoryUsage := int64(len(va.X)*Float32Size + len(va.Y)*Float32Size + len(va.Z)*Float32Size)
	cacheLines := (len(va.X) * Float32Size / CacheLineSize) + 1

	return Stats{
		Count:            va.Count,
		Capacity:         va.Capacity,
		MemoryUsageBytes: memoryUsage,
		CacheLinesUsed:   cacheLines * 3, // 3개 배열
		SimdOpsPerCycle:  SimdLaneCount,
	}
}

