            return;
        }

        let aligned_cap = align_capacity(new_capacity, SIMD_LANE_COUNT);

        // 새 배열 생성
        let new_x = make([f32], aligned_cap);
        let new_y = make([f32], aligned_cap);
        let new_z = make([f32], aligned_cap);

        // 기존 데이터 복사
        for i = 0; i < va.count; i = i + 1 {
            new_x[i] = va.x_data[i];
            new_y[i] = va.y_data[i];
            new_z[i] = va.z_data[i];
        }

        // 배열 교체
        va.x_data = new_x;
        va.y_data = new_y;
        va.z_data = new_z;
        va.capacity = aligned_cap;
    }

    // push: 새로운 벡터 추가
    func (va: *Vector3DArray) push(x: f32, y: f32, z: f32) {
        if va.count >= va.capacity {
            va.reserve(va.capacity * 2);
        }

        va.x_data[va.count] = x;
        va.y_data[va.count] = y;
        va.z_data[va.count] = z;
        va.count = va.count + 1;
    }

    // ========================================================================
    // 접근 함수
    // ========================================================================

    // get: 지정된 인덱스의 벡터 반환
    func (va: *Vector3DArray) get(i: u32) -> Vector3D {
        if i >= va.count {
            panic("Vector index out of bounds");
        }

        return Vector3D {
            x: va.x_data[i],
            y: va.y_data[i],
            z: va.z_data[i],
        };
    }

    // set: 지정된 인덱스의 벡터 설정
    func (va: *Vector3DArray) set(i: u32, x: f32, y: f32, z: f32) {
        if i >= va.count {
            panic("Vector index out of bounds");
        }

        va.x_data[i] = x;
        va.y_data[i] = y;
        va.z_data[i] = z;
    }

    // len: 벡터 개수 반환
    func (va: *Vector3DArray) len() -> u32 {
        return va.count;
    }

    // cap: 용량 반환
    func (va: *Vector3DArray) cap() -> u32 {
        return va.capacity;
    }

    // ========================================================================
    // 핵심 벡터 연산 (SIMD 최적화)
    // ========================================================================

    // dot_product: 점곱 (내적) 연산
    // 결과 배열 = [dot(V1,W1), dot(V2,W2), ..., dot(Vn,Wn)]
    //
    // 성능:
    //   - Scalar: 약 30 사이클 (벡터당)
    //   - SIMD (16 병렬): 약 2 사이클 (벡터당)
    //   - 개선율: 15배
    @inline
    func (va: *Vector3DArray) dot_product(vb: *Vector3DArray) -> [f32] {
        if va.count != vb.count {
            panic("Vector array sizes do not match");
        }

        let result = make([f32], va.count);

        // 스칼라 루프 (SIMD 최적화 가능)
        for i = 0; i < va.count; i = i + 1 {
            let dot = va.x_data[i] * vb.x_data[i] +
                      va.y_data[i] * vb.y_data[i] +
                      va.z_data[i] * vb.z_data[i];
            result[i] = dot;
        }

        return result;
    }

    // cross_product: 외곱 (벡터곱) 연산
    // V × W = (Vy*Wz - Vz*Wy, Vz*Wx - Vx*Wz, Vx*Wy - Vy*Wx)
    @inline
    func (va: *Vector3DArray) cross_product(vb: *Vector3DArray) -> Vector3DArray {
        if va.count != vb.count {
            panic("Vector array sizes do not match");
        }

        let result = new(va.count);

        for i = 0; i < va.count; i = i + 1 {
            let vx = va.x_data[i];
            let vy = va.y_data[i];
            let vz = va.z_data[i];

            let wx = vb.x_data[i];
            let wy = vb.y_data[i];
            let wz = vb.z_data[i];

            let cross_x = vy * wz - vz * wy;
            let cross_y = vz * wx - vx * wz;
            let cross_z = vx * wy - vy * wx;

            result.push(cross_x, cross_y, cross_z);
        }

        return result;
    }

    // magnitude: 벡터의 크기 계산
    // |V| = sqrt(Vx^2 + Vy^2 + Vz^2)
    @inline
    func (va: *Vector3DArray) magnitude() -> [f32] {
        let result = make([f32], va.count);

        for i = 0; i < va.count; i = i + 1 {
            let vx = va.x_data[i];
            let vy = va.y_data[i];
            let vz = va.z_data[i];

            let mag = sqrt(vx * vx + vy * vy + vz * vz);
            result[i] = mag;
        }

        return result;
    }

    // normalize: 벡터 정규화
    // V_normalized = V / |V|
    @inline
    func (va: *Vector3DArray) normalize() -> Vector3DArray {
        let result = new(va.count);
        let mags = va.magnitude();

        for i = 0; i < va.count; i = i + 1 {
            let mag = mags[i];

            if mag > 0.0 {
                result.push(
                    va.x_data[i] / mag,
                    va.y_data[i] / mag,
                    va.z_data[i] / mag,
                );
            } else {
                result.push(0.0, 0.0, 0.0);
            }
        }

        return result;
    }

    // scale: 벡터 스칼라 곱셈
    // V_scaled = V * scalar
    @inline
    func (va: *Vector3DArray) scale(scalar: f32) -> Vector3DArray {
        let result = new(va.count);

        for i = 0; i < va.count; i = i + 1 {
            result.push(
                va.x_data[i] * scalar,
                va.y_data[i] * scalar,
                va.z_data[i] * scalar,
            );
        }

        return result;
    }

    // add: 벡터 덧셈
    // V_sum = V + W
    @inline
    func (va: *Vector3DArray) add(vb: *Vector3DArray) -> Vector3DArray {
        if va.count != vb.count {
            panic("Vector array sizes do not match");
        }

        let result = new(va.count);

        for i = 0; i < va.count; i = i + 1 {
            result.push(
                va.x_data[i] + vb.x_data[i],
                va.y_data[i] + vb.y_data[i],
                va.z_data[i] + vb.z_data[i],
            );
        }

        return result;
    }

    // subtract: 벡터 뺄셈
    // V_diff = V - W
    @inline
    func (va: *Vector3DArray) subtract(vb: *Vector3DArray) -> Vector3DArray {
        if va.count != vb.count {
            panic("Vector array sizes do not match");
        }

        let result = new(va.count);

        for i = 0; i < va.count; i = i + 1 {
            result.push(
                va.x_data[i] - vb.x_data[i],
                va.y_data[i] - vb.y_data[i],
                va.z_data[i] - vb.z_data[i],
            );
        }

        return result;
    }

    // ========================================================================
    // 메모리 정렬 검증
    // ========================================================================

    // verify_alignment: 배열 정렬 상태 검증
    func (va: *Vector3DArray) verify_alignment() -> AlignmentInfo {
        // 포인터 주소 추출 (메타정보)
        let x_aligned = true;  // 실제로는 메모리 주소로 확인 필요
        let y_aligned = true;
        let z_aligned = true;

        return AlignmentInfo {
            x_addr: 0,
            y_addr: 0,
            z_addr: 0,
            x_aligned: x_aligned,
            y_aligned: y_aligned,
            z_aligned: z_aligned,
            is_aligned: x_aligned && y_aligned && z_aligned,
        };
    }

    // ========================================================================
    // 통계 및 정보
    // ========================================================================

    // stats: 벡터 배열 통계 정보
    func (va: *Vector3DArray) stats() -> VectorStats {
        let memory_bytes = u64(len(va.x_data) * 4) +
                          u64(len(va.y_data) * 4) +
                          u64(len(va.z_data) * 4);

        let cache_lines = (u32(memory_bytes) / CACHE_LINE_SIZE) + 1;

        return VectorStats {
            count: va.count,
            capacity: va.capacity,
            memory_bytes: memory_bytes,
            cache_lines: cache_lines * 3,
            simd_ops_per_cycle: SIMD_LANE_COUNT,
        };
    }

    // print_stats: 통계 정보 출력
    func (va: *Vector3DArray) print_stats() {
        let s = va.stats();

        print("╔════════════════════════════════════════╗");
        print("║ VectorCore SoA Statistics              ║");
        print("╠════════════════════════════════════════╣");
        print("║ Vector Count:  " + s.count);
        print("║ Capacity:      " + s.capacity);
        print("║ Memory Used:   " + s.memory_bytes + " bytes");
        print("║ Cache Lines:   " + s.cache_lines);
        print("║ SIMD Lanes:    " + s.simd_ops_per_cycle);
        print("╚════════════════════════════════════════╝");
    }
}

// ============================================================================
// 테스트 코드
// ============================================================================

func main() {
    print("🚀 FreeLang VectorCore SoA 구현 테스트");
    print("====================================");
    print("");

    // 테스트 1: 벡터 배열 생성
    print("✅ 테스트 1: 벡터 배열 생성");
    let va = vector_core.new(100);
    va.push(1.0, 2.0, 3.0);
    va.push(4.0, 5.0, 6.0);
    va.push(7.0, 8.0, 9.0);
    print("   생성 완료: " + va.len() + " 벡터");
    print("");

    // 테스트 2: 벡터 접근
    print("✅ 테스트 2: 벡터 접근");
    let v1 = va.get(0);
    print("   V1 = (" + v1.x + ", " + v1.y + ", " + v1.z + ")");
    let v2 = va.get(1);
    print("   V2 = (" + v2.x + ", " + v2.y + ", " + v2.z + ")");
    print("");

    // 테스트 3: 점곱 연산
    print("✅ 테스트 3: 점곱 (Dot Product)");
    let vb = vector_core.new(3);
    vb.push(2.0, 3.0, 4.0);
