    // 테스트 5: 벡터 정규화
    print("✅ 테스트 5: 벡터 정규화 (Normalize)");
    let vc = va.normalize();
    let v1_norm = vc.get(0);
    print("   V1_normalized = (" + v1_norm.x + ", " + v1_norm.y + ", " + v1_norm.z + ")");
    print("");

    // 테스트 6: 벡터 덧셈
    print("✅ 테스트 6: 벡터 덧셈 (Add)");
    let sum = va.add(vb);
    let v_sum = sum.get(0);
    print("   V1 + V2 = (" + v_sum.x + ", " + v_sum.y + ", " + v_sum.z + ")");
    print("");

    // 테스트 7: 통계
    print("✅ 테스트 7: 메모리 통계");
    va.print_stats();
    print("");

    // 테스트 8: 정렬 검증
    print("✅ 테스트 8: 메모리 정렬 검증");
