    print("   X 정렬: " + align.x_aligned);
    print("   Y 정렬: " + align.y_aligned);
    print("   Z 정렬: " + align.z_aligned);
    print("   전체 정렬: " + align.is_aligned);
    print("");

    print("✨ 모든 테스트 완료!");
