// ============================================================================
// Aligned Memory Allocator (64-byte Cache-Line Aligned)
// FreeLang 구현 - Zero-Copy DB용 메모리 관리자
// ============================================================================
//
// 목표: 모든 메모리 할당을 64바이트 경계에 정렬하여
//       CPU 캐시 효율을 극대화하고 SIMD 성능을 최적화
//
// 원리:
//   - CPU L1 캐시라인: 64바이트
//   - 정렬 메모리: 캐시라인 경계에서 시작
//   - SIMD 연산: 메모리 접근 오버헤드 감소 → 1-2% 추가 성능 향상
// ============================================================================

module memory {
    // ========================================================================
    // 상수
    // ========================================================================

    const CACHE_LINE_SIZE: u32 = 64;          // 캐시라인 크기
    const MIN_ALIGNMENT: u32 = 16;            // 최소 정렬 (128비트)
    const PAGE_SIZE: u32 = 4096;              // 메모리 페이지 크기
    const POOL_INITIAL_SIZE: u32 = 1024;      // 초기 풀 크기

    // ========================================================================
    // 데이터 구조
    // ========================================================================

    // MemoryBlock은 할당된 메모리 블록의 메타정보
    struct MemoryBlock {
        ptr: u64;              // 메모리 포인터
        size: u32;             // 할당된 크기
        alignment: u32;        // 정렬 바이트
        is_aligned: bool;      // 정렬 여부
        user_ptr: u64;         // 사용자 포인터 (패딩 이후)
    }

    // AlignedAllocator는 정렬된 메모리를 관리하는 할당자
    struct AlignedAllocator {
        alignment: u32;        // 기본 정렬 (64)
        blocks: [MemoryBlock]; // 할당된 블록 목록
        total_allocated: u64;  // 총 할당 크기
        total_wasted: u64;     // 정렬으로 인한 낭비 크기
    }

    // AlignmentInfo는 정렬 상태 정보
    struct AlignmentInfo {
        address: u64;
        alignment_bytes: u32;
        is_aligned: bool;
        next_aligned_addr: u64;
        padding_needed: u32;
    }

    // AllocationStats는 할당 통계
    struct AllocationStats {
        total_blocks: u32;
        total_allocated: u64;
        total_wasted: u64;
        avg_utilization: f32;
    }

    // ========================================================================
    // 정렬 계산 함수
    // ========================================================================

    // align_up: 주어진 값을 정렬 크기로 올림
    // 예: align_up(100, 64) = 128
    @inline
    func align_up(value: u32, alignment: u32) -> u32 {
        if alignment == 0 {
            return value;
        }
        return ((value + alignment - 1) / alignment) * alignment;
    }

    // align_down: 주어진 값을 정렬 크기로 내림
    // 예: align_down(100, 64) = 64
    @inline
    func align_down(value: u32, alignment: u32) -> u32 {
        if alignment == 0 {
            return value;
        }
        return (value / alignment) * alignment;
    }

    // is_aligned: 값이 정렬되었는지 확인
    @inline
    func is_aligned(value: u64, alignment: u32) -> bool {
        return (value % u64(alignment)) == 0;
    }

    // calc_padding: 정렬을 위한 패딩 계산
    // 반환: (패딩 바이트, 정렬된 주소)
    @inline
    func calc_padding(ptr: u64, alignment: u32) -> (u32, u64) {
        let remainder = u32(ptr % u64(alignment));
        if remainder == 0 {
            return (0, ptr);
        }

        let padding = alignment - remainder;
        let aligned_addr = ptr + u64(padding);
        return (padding, aligned_addr);
    }

    // ========================================================================
    // Branchless 최적화 함수
    // ========================================================================

    // max_branchless: 분기 없이 최댓값 계산
    // if-else를 비트 연산으로 대체하여 파이프라인 중단 방지
    @inline
    func max_branchless(a: i32, b: i32) -> i32 {
        // a >= b 인 경우 a, 아니면 b를 반환
        // 분기 대신 비트 마스킹 사용
        let diff = a - b;
        let sign = (diff >> 31);  // 음수면 -1 (모든 비트 1), 양수면 0
        return b + ((a - b) & ~sign);
    }

    // min_branchless: 분기 없이 최솟값 계산
    @inline
    func min_branchless(a: i32, b: i32) -> i32 {
        let diff = a - b;
        let sign = (diff >> 31);
        return a - ((a - b) & ~sign);
    }

    // clamp_branchless: 값을 범위 내로 제한 (분기 없음)
    // SIMD 마스킹과 동일한 원리
    @inline
    func clamp_branchless(value: i32, min: i32, max: i32) -> i32 {
        let clamped = max_branchless(min, min_branchless(value, max));
        return clamped;
    }

    // abs_branchless: 절댓값 계산 (분기 없음)
    @inline
    func abs_branchless(x: i32) -> i32 {
        let mask = x >> 31;      // 음수면 -1, 양수면 0
        return (x + mask) ^ mask; // XOR로 부호 반전
    }

    // ========================================================================
    // 할당자 생성 및 초기화
    // ========================================================================

    // new: 새로운 정렬된 할당자 생성
    func new() -> AlignedAllocator {
        return AlignedAllocator {
            alignment: CACHE_LINE_SIZE,
            blocks: make([MemoryBlock], 0),
            total_allocated: 0,
            total_wasted: 0,
        };
    }

    // ========================================================================
    // 메모리 할당 함수
    // ========================================================================

    // allocate: 64바이트 정렬된 메모리 할당
    func (a: *AlignedAllocator) allocate(size: u32) -> u64 {
        if size == 0 {
            panic("Cannot allocate zero bytes");
        }

        // 할당 크기 = 원본 크기 + 패딩 (최악의 경우 63바이트)
        let padded_size = size + (a.alignment - 1);

        // 가상 메모리 할당 (실제 구현에서는 malloc 호출)
        let ptr = virtual_alloc(padded_size);

        // 정렬 계산
        let (padding, aligned_ptr) = calc_padding(ptr, a.alignment);

        // 블록 정보 기록
        let block = MemoryBlock {
            ptr: ptr,
            size: size,
            alignment: a.alignment,
            is_aligned: padding == 0,
            user_ptr: aligned_ptr,
        };

        a.blocks.push(block);
        a.total_allocated = a.total_allocated + u64(padded_size);
        a.total_wasted = a.total_wasted + u64(padding);

        return aligned_ptr;
    }

    // allocate_aligned: 임의의 정렬 값으로 메모리 할당
    func (a: *AlignedAllocator) allocate_aligned(size: u32, alignment: u32) -> u64 {
        if size == 0 {
            panic("Cannot allocate zero bytes");
        }

        // 정렬 값 검증
        let aligned_alignment = max_branchless(i32(alignment), i32(MIN_ALIGNMENT));
        let align_u32 = u32(aligned_alignment);

        // 할당 크기 조정
        let padded_size = size + (align_u32 - 1);

        // 메모리 할당
        let ptr = virtual_alloc(padded_size);
        let (padding, aligned_ptr) = calc_padding(ptr, align_u32);

        // 블록 기록
        let block = MemoryBlock {
            ptr: ptr,
            size: size,
            alignment: align_u32,
            is_aligned: padding == 0,
            user_ptr: aligned_ptr,
        };

        a.blocks.push(block);
        a.total_allocated = a.total_allocated + u64(padded_size);
        a.total_wasted = a.total_wasted + u64(padding);

        return aligned_ptr;
    }

    // ========================================================================
    // 메모리 해제
    // ========================================================================

    // deallocate: 메모리 해제
    func (a: *AlignedAllocator) deallocate(ptr: u64) {
        // 블록 찾기
        for i = 0; i < len(a.blocks); i = i + 1 {
            if a.blocks[i].user_ptr == ptr {
                // 메모리 해제
                virtual_free(a.blocks[i].ptr, a.blocks[i].size);

                // 블록 제거 (간단한 방식)
                a.blocks[i] = MemoryBlock {};
                break;
            }
        }
    }

    // ========================================================================
    // 정렬 검증
    // ========================================================================

    // verify_alignment: 할당된 메모리의 정렬 상태 검증
    func (a: *AlignedAllocator) verify_alignment(ptr: u64) -> AlignmentInfo {
        let (padding, next_aligned) = calc_padding(ptr, a.alignment);
        let aligned = is_aligned(ptr, a.alignment);

        return AlignmentInfo {
            address: ptr,
            alignment_bytes: a.alignment,
            is_aligned: aligned,
            next_aligned_addr: next_aligned,
            padding_needed: padding,
        };
    }

    // check_all_aligned: 모든 할당이 정렬되었는지 확인
    func (a: *AlignedAllocator) check_all_aligned() -> bool {
        for i = 0; i < len(a.blocks); i = i + 1 {
            if !a.blocks[i].is_aligned {
                return false;
            }
        }
        return true;
    }

    // ========================================================================
    // 통계
    // ========================================================================

    // stats: 할당 통계 반환
    func (a: *AlignedAllocator) stats() -> AllocationStats {
        let total_useful = a.total_allocated - a.total_wasted;
        let utilization = f32(total_useful) / f32(a.total_allocated);

        return AllocationStats {
            total_blocks: u32(len(a.blocks)),
            total_allocated: a.total_allocated,
            total_wasted: a.total_wasted,
            avg_utilization: utilization,
        };
    }

    // print_stats: 통계 출력
    func (a: *AlignedAllocator) print_stats() {
        let s = a.stats();

        print("╔════════════════════════════════════════╗");
        print("║ Aligned Allocator Statistics           ║");
        print("╠════════════════════════════════════════╣");
        print("║ Cache Line Size:     " + CACHE_LINE_SIZE + " bytes");
        print("║ Total Blocks:        " + s.total_blocks);
        print("║ Total Allocated:     " + s.total_allocated + " bytes");
        print("║ Wasted (Padding):    " + s.total_wasted + " bytes");
        print("║ Utilization:         " + s.avg_utilization * 100.0 + "%");
        print("╚════════════════════════════════════════╝");
    }

    // ========================================================================
    // 가상 메모리 함수 (실제로는 OS 호출)
    // ========================================================================

    // virtual_alloc: 메모리 할당 (모의)
    func virtual_alloc(size: u32) -> u64 {
        // 실제 구현에서는:
        // - Linux: malloc() 또는 aligned_alloc()
        // - Windows: VirtualAlloc()
        // - MacOS: malloc_aligned()

        // 여기서는 임의의 주소 반환 (테스트용)
        return u64(size);
    }

    // virtual_free: 메모리 해제 (모의)
    func virtual_free(ptr: u64, size: u32) {
        // 실제 구현에서는 free() 또는 VirtualFree() 호출
    }
}

