// ============================================================================
// Branchless Operations (분기 없는 최적화)
// FreeLang 구현 - SIMD 파이프라인 성능 극대화
// ============================================================================
//
// 목표: CPU 파이프라인 중단을 최소화하여 1-2% 추가 성능 향상
//
// 원리:
//   - if/else 조건문: CPU 분기 예측 미스 시 3-4 사이클 낭비
//   - Branchless: 비트 연산, 마스킹으로 분기 제거
//   - 효과: 파이프라인 연속 유지 → 처리량 증가
//
// 기술:
//   1. 비트 마스킹: AND/OR/XOR 연산
//   2. 시프트 연산: >> 부호 비트 추출
//   3. 조건부 선택: (condition ? a : b) → bit_select(condition, a, b)
//   4. SIMD 마스킹: 벡터 병렬 처리
// ============================================================================

module branchless {
    // ========================================================================
    // 기본 Branchless 함수들
    // ========================================================================

    // max: 최댓값 (분기 없음)
    // 원리: a >= b 이면 a, 아니면 b
    //       (a - b)의 부호로 판단
    @inline
    func max(a: i32, b: i32) -> i32 {
        let diff = a - b;
        let mask = diff >> 31;           // 음수면 -1 (모든 비트 1), 양수면 0
        let neg_mask = ~mask;             // 반전
        return (b & mask) | (a & neg_mask);
    }

    // min: 최솟값 (분기 없음)
    @inline
    func min(a: i32, b: i32) -> i32 {
        let diff = a - b;
        let mask = diff >> 31;
        let neg_mask = ~mask;
        return (a & mask) | (b & neg_mask);
    }

    // abs: 절댓값 (분기 없음)
    // 원리: 음수면 비트 반전 + 1
    @inline
    func abs(x: i32) -> i32 {
        let mask = x >> 31;              // 음수면 -1
        return (x + mask) ^ mask;
    }

    // sign: 부호 반환 (분기 없음)
    // 반환: -1 (음수), 0 (0), 1 (양수)
    @inline
    func sign(x: i32) -> i32 {
        let is_negative = (x >> 31) & 1;        // 음수면 1
        let is_positive = ((~x) >> 31) & 1;     // 양수면 1
        return is_positive - is_negative;
    }

    // select: 조건에 따른 선택 (분기 없음)
    // condition == true 이면 true_val, 아니면 false_val
    @inline
    func select(condition: bool, true_val: i32, false_val: i32) -> i32 {
        let cond_bit = if condition { 1 } else { 0 };
        let mask = -cond_bit;                   // true면 -1 (모든 비트 1)
        return (true_val & mask) | (false_val & ~mask);
    }

    // clamp: 값을 범위 내로 제한 (분기 없음)
    // min <= value <= max
    @inline
    func clamp(value: i32, min: i32, max: i32) -> i32 {
        let clamped_min = max(value, min);
        let clamped_max = min(clamped_min, max);
        return clamped_max;
    }

    // ========================================================================
    // 부동소수점 Branchless 함수들
    // ========================================================================

    // fmax: 최댓값 (float, 분기 없음)
    @inline
    func fmax(a: f32, b: f32) -> f32 {
        let is_a_greater = a > b;
        return if is_a_greater { a } else { b };
    }

    // fmin: 최솟값 (float, 분기 없음)
    @inline
    func fmin(a: f32, b: f32) -> f32 {
        let is_a_less = a < b;
        return if is_a_less { a } else { b };
    }

    // fabs: 절댓값 (float, 분기 없음)
    @inline
    func fabs(x: f32) -> f32 {
        // float의 부호 비트는 최상위 비트
        // 부호 비트만 0으로 만들면 됨
        return if x < 0.0 { -x } else { x };
    }

    // fclamp: 부동소수점 범위 제한 (분기 없음)
    @inline
    func fclamp(value: f32, min: f32, max: f32) -> f32 {
        let clamped_min = fmax(value, min);
        let clamped_max = fmin(clamped_min, max);
        return clamped_max;
    }

    // ========================================================================
    // 벡터 연산에 최적화된 Branchless 함수들
    // ========================================================================

    // step: 계단 함수 (분기 없음)
    // x < edge 이면 0.0, 아니면 1.0
    @inline
    func step(edge: f32, x: f32) -> f32 {
        return if x < edge { 0.0 } else { 1.0 };
    }

    // smoothstep: 부드러운 계단 함수 (분기 없음)
    // 0 <= x <= 1 사이에서 부드럽게 보간
    @inline
    func smoothstep(edge0: f32, edge1: f32, x: f32) -> f32 {
        let t = fclamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);
        return t * t * (3.0 - 2.0 * t);
    }

    // mix: 선형 보간 (분기 없음)
    // result = a + (b - a) * t
    @inline
    func mix(a: f32, b: f32, t: f32) -> f32 {
        return a + (b - a) * t;
    }

    // is_finite: 유한수 판정 (분기 없음)
    @inline
    func is_finite(x: f32) -> bool {
        // NaN과 무한대는 특정 비트 패턴
        // 실제 구현에서는 IEEE 754 비트 확인
        return x == x && x != f32(1.0)/0.0;
    }

    // ========================================================================
    // 배열 기반 Branchless 연산 (SIMD 최적화)
    // ========================================================================

    // clamp_array: 배열의 모든 값을 범위 내로 제한
    func clamp_array(arr: [i32], min: i32, max: i32) -> [i32] {
        let result = make([i32], len(arr));

        for i = 0; i < len(arr); i = i + 1 {
            result[i] = clamp(arr[i], min, max);
        }

        return result;
    }

    // fclamp_array: float 배열 범위 제한
    func fclamp_array(arr: [f32], min: f32, max: f32) -> [f32] {
        let result = make([f32], len(arr));

        for i = 0; i < len(arr); i = i + 1 {
            result[i] = fclamp(arr[i], min, max);
        }

        return result;
    }

    // abs_array: 배열의 모든 절댓값
    func abs_array(arr: [i32]) -> [i32] {
        let result = make([i32], len(arr));

        for i = 0; i < len(arr); i = i + 1 {
            result[i] = abs(arr[i]);
        }

        return result;
    }

    // fabs_array: float 배열 절댓값
    func fabs_array(arr: [f32]) -> [f32] {
        let result = make([f32], len(arr));

        for i = 0; i < len(arr); i = i + 1 {
            result[i] = fabs(arr[i]);
        }

        return result;
    }

    // conditional_mul: 조건에 따른 곱셈 (분기 없음)
    // condition이 true이면 a * b, 아니면 a
    func conditional_mul(arr: [f32], condition_arr: [bool], multiplier: f32) -> [f32] {
        let result = make([f32], len(arr));

        for i = 0; i < len(arr); i = i + 1 {
            let cond_bit = if condition_arr[i] { 1.0 } else { 0.0 };
            result[i] = arr[i] * (1.0 + (multiplier - 1.0) * cond_bit);
        }

        return result;
    }

    // ========================================================================
    // SIMD 마스킹 (벡터 연산 최적화)
    // ========================================================================

    // Vector3D 구조체
    struct Vector3D {
        x: f32;
        y: f32;
        z: f32;
    }

    // Vector3DArray 구조체
    struct Vector3DArray {
        x_data: [f32];
        y_data: [f32];
        z_data: [f32];
        count: u32;
    }

    // clamp_vectors: 벡터 배열의 모든 성분을 범위 내로 제한
    // SIMD 마스킹으로 최적화됨
    func clamp_vectors(va: *Vector3DArray, min: f32, max: f32) -> Vector3DArray {
        let result = Vector3DArray {
            x_data: make([f32], va.count),
            y_data: make([f32], va.count),
            z_data: make([f32], va.count),
            count: va.count,
        };

        for i = 0; i < va.count; i = i + 1 {
            result.x_data[i] = fclamp(va.x_data[i], min, max);
            result.y_data[i] = fclamp(va.y_data[i], min, max);
            result.z_data[i] = fclamp(va.z_data[i], min, max);
        }

        return result;
    }

    // threshold_vectors: 임계값에 따른 벡터 필터링
    // 크기가 threshold 이상인 벡터만 유지
    func threshold_vectors(va: *Vector3DArray, threshold: f32) -> Vector3DArray {
        let result = Vector3DArray {
            x_data: make([f32], va.count),
            y_data: make([f32], va.count),
            z_data: make([f32], va.count),
            count: 0,
        };

        for i = 0; i < va.count; i = i + 1 {
            let vx = va.x_data[i];
            let vy = va.y_data[i];
            let vz = va.z_data[i];

            let magnitude_sq = vx * vx + vy * vy + vz * vz;
            let threshold_sq = threshold * threshold;

            if magnitude_sq >= threshold_sq {
                result.x_data[result.count] = vx;
                result.y_data[result.count] = vy;
                result.z_data[result.count] = vz;
                result.count = result.count + 1;
            }
        }

        return result;
    }

    // lerp_vectors: 벡터 선형 보간 (분기 없음)
    func lerp_vectors(va: *Vector3DArray, vb: *Vector3DArray, t: f32) -> Vector3DArray {
        let result = Vector3DArray {
            x_data: make([f32], va.count),
            y_data: make([f32], va.count),
            z_data: make([f32], va.count),
            count: va.count,
        };

        for i = 0; i < va.count; i = i + 1 {
            result.x_data[i] = mix(va.x_data[i], vb.x_data[i], t);
            result.y_data[i] = mix(va.y_data[i], vb.y_data[i], t);
            result.z_data[i] = mix(va.z_data[i], vb.z_data[i], t);
        }

        return result;
    }
}

