func main() {
    print("🚀 FreeLang Branchless Operations 테스트");
    print("=======================================");
    print("");

    // 테스트 1: 정수 연산
    print("✅ 테스트 1: 정수 Branchless 연산");
    let max_result = branchless.max(10, 20);
    print("   max(10, 20) = " + max_result);
    let min_result = branchless.min(10, 20);
    print("   min(10, 20) = " + min_result);
    let abs_result = branchless.abs(-42);
    print("   abs(-42) = " + abs_result);
    print("");

    // 테스트 2: 범위 제한
    print("✅ 테스트 2: 범위 제한 (Clamp)");
    let clamped = branchless.clamp(150, 0, 100);
    print("   clamp(150, 0, 100) = " + clamped);
    let clamped2 = branchless.clamp(-50, 0, 100);
    print("   clamp(-50, 0, 100) = " + clamped2);
    print("");

    // 테스트 3: 부동소수점 연산
    print("✅ 테스트 3: 부동소수점 Branchless 연산");
    let fmax_result = branchless.fmax(3.14, 2.71);
    print("   fmax(3.14, 2.71) = " + fmax_result);
    let fabs_result = branchless.fabs(-2.5);
    print("   fabs(-2.5) = " + fabs_result);
    print("");

    // 테스트 4: 선형 보간
    print("✅ 테스트 4: 선형 보간 (Mix)");
    let mixed = branchless.mix(10.0, 20.0, 0.5);
    print("   mix(10.0, 20.0, 0.5) = " + mixed);
    print("");

    // 테스트 5: 배열 연산
    print("✅ 테스트 5: 배열 Branchless 연산");
    let arr = [i32]{-10, 50, 150, -100, 30};
    let clamped_arr = branchless.clamp_array(arr, 0, 100);
    print("   clamp_array([-10, 50, 150, -100, 30], 0, 100)");
    for i = 0; i < len(clamped_arr); i = i + 1 {
        print("   [" + i + "] = " + clamped_arr[i]);
    }
    print("");

    // 테스트 6: Smoothstep
    print("✅ 테스트 6: Smoothstep 함수");
    let smooth1 = branchless.smoothstep(0.0, 1.0, 0.25);
    let smooth2 = branchless.smoothstep(0.0, 1.0, 0.5);
    let smooth3 = branchless.smoothstep(0.0, 1.0, 0.75);
    print("   smoothstep(0.0, 1.0, 0.25) = " + smooth1);
    print("   smoothstep(0.0, 1.0, 0.5) = " + smooth2);
    print("   smoothstep(0.0, 1.0, 0.75) = " + smooth3);
    print("");

    print("✨ 모든 테스트 완료!");
    print("");
    print("💡 성능 개선:");
    print("   - if/else 제거: CPU 파이프라인 중단 방지");
    print("   - 비트 연산: 단일 사이클 완료");
    print("   - SIMD 마스킹: 벡터 병렬 처리");
    print("   - 예상 개선율: 1-2% (Phase 1.3 누적)");
}
